1	// Raft 跟随者本地日志复制：在单次命令调用内维护节点状态，顺序应用
2	// 领导者发来的 AppendEntries 请求。本文件只做纯逻辑处理，不连接网络。
3	package mevwatch
4	
5	import (
6		"encoding/json"
7		"fmt"
8	)
9	
10	// LogEntry 是一条日志：Index 从 1 开始连续编号，Term 为该条目写入时的任期，
11	// Command 为字符串命令。
12	type LogEntry struct {
13		Index   int    `json:"index"`
14		Term    int    `json:"term"`
15		Command string `json:"command"`
16	}
17	
18	// InitialState 是跟随者在本次调用开始时的状态。
19	type InitialState struct {
20		// CurrentTerm 是该节点已知的最新任期。
21		CurrentTerm int `json:"currentTerm"`
22		// CommittedIndex 是已经提交（不可覆盖）的最高日志索引。
23		CommittedIndex int `json:"committedIndex"`
24		// Log 是从索引 1 开始的连续日志。
25		Log []LogEntry `json:"log"`
26	}
27	
28	// AppendRequest 是顺序到达的一次日志复制请求。
29	type AppendRequest struct {
30		// Term 是领导者任期。
31		Term int `json:"term"`
32		// PrevLogIndex / PrevLogTerm 是新条目紧邻的前一条日志的索引与任期；
33		// 均为 0 表示日志起点（哨兵），不是真实条目。
34		PrevLogIndex int `json:"prevLogIndex"`
35		PrevLogTerm  int `json:"prevLogTerm"`
36		// Entries 是待追加的条目，必须从前一条索引加 1 开始连续排列，允许为空。
37		Entries []LogEntry `json:"entries"`
38		// LeaderCommit 是领导者已提交索引。
39		LeaderCommit int `json:"leaderCommit"`
40	}
41	
42	// AppendResult 是单条请求处理后节点对该请求的答复。
43	type AppendResult struct {
44		// Accepted 表示本次复制是否成功。
45		Accepted bool `json:"accepted"`
46		// Reason 是成功 ok 或被拒绝的具体原因。
47		Reason string `json:"reason"`
48		// Term 是处理后节点的当前任期（较高任期请求即便最终被拒绝也会留下任期更新）。
49		Term int `json:"term"`
50		// CommittedIndex 是处理后节点的已提交索引。
51		CommittedIndex int `json:"committedIndex"`
52		// AppliedIndex / ApplyError 仅在启用键值应用（ReplicateOptions.ApplyKV）
53		// 时填充：处理本请求后已应用的最高日志索引与首个应用错误。
54		// 复制是否被接受与命令应用是否失败相互独立表达。
55		AppliedIndex *int        `json:"appliedIndex,omitempty"`
56		ApplyError   *ApplyError `json:"applyError,omitempty"`
57		// applyFields 为 true 时 JSON 输出总是带上 appliedIndex 与 applyError
58		// （无错误时 applyError 为 null）；为 false 时两个字段完全不出现。
59		applyFields bool
60	}
61	
62	// MarshalJSON 在未启用键值应用时保持原有输出形状；启用时强制输出
63	// appliedIndex 与 applyError（错误为空输出 null）。
64	func (r AppendResult) MarshalJSON() ([]byte, error) {
65		type alias AppendResult
66		if !r.applyFields {
67			return json.Marshal(alias(r))
68		}
69		applied := 0
70		if r.AppliedIndex != nil {
71			applied = *r.AppliedIndex
72		}
73		return json.Marshal(struct {
74			alias
75			AppliedIndex int         `json:"appliedIndex"`
76			ApplyError   *ApplyError `json:"applyError"`
77		}{
78			alias:        alias(r),
79			AppliedIndex: applied,
80			ApplyError:   r.ApplyError,
81		})
82	}
83	
84	// UnmarshalJSON 读取结果时按 JSON 中是否出现应用字段恢复 applyFields：
85	// 出现 appliedIndex 或 applyError 时视为启用键值应用的结果，再次编码会原样
86	// 保留这些字段（含 0、null）；未出现时按未启用处理，且整个对象被完整替换，
87	// 不会残留上一次读入的应用状态。字段类型错误照常返回解码错误。
88	func (r *AppendResult) UnmarshalJSON(data []byte) error {
89		type alias AppendResult
90		var decoded alias
91		if err := json.Unmarshal(data, &decoded); err != nil {
92			return err
93		}
94		present, err := jsonHasAnyKey(data, "appliedIndex", "applyError")
95		if err != nil {
96			return err
97		}
98		*r = AppendResult(decoded)
99		r.applyFields = present
100		return nil
101	}
102	
103	// jsonHasAnyKey 报告 JSON 对象中是否出现任一给定键。
104	func jsonHasAnyKey(data []byte, keys ...string) (bool, error) {
105		var raw map[string]json.RawMessage
106		if err := json.Unmarshal(data, &raw); err != nil {
107			return false, err
108		}
109		for _, key := range keys {
110			if _, ok := raw[key]; ok {
111				return true, nil
112			}
113		}
114		return false, nil
115	}
116	
117	// ReplicateOutput 是整次调用的结果。
118	type ReplicateOutput struct {
119		// Results 与输入请求一一对应。
120		Results []AppendResult `json:"results"`
121		// FinalTerm / FinalCommittedIndex 是最终状态。
122		FinalTerm           int `json:"finalTerm"`
123		FinalCommittedIndex int `json:"finalCommittedIndex"`
124		// FinalLog 是处理完所有请求后的完整日志。
125		FinalLog []LogEntry `json:"finalLog"`
126		// FinalAppliedIndex / FinalKV / FinalApplyError 仅在启用键值应用时填充：
127		// 最终已应用的最高日志索引、最终键值表与首个应用错误。没有请求时同样
128		// 反映初始已提交前缀的应用结果。
129		FinalAppliedIndex *int              `json:"finalAppliedIndex,omitempty"`
130		FinalKV           map[string]string `json:"finalKV,omitempty"`
131		FinalApplyError   *ApplyError       `json:"finalApplyError,omitempty"`
132		// applyFields 含义同 AppendResult.applyFields。
133		applyFields bool
134	}
135	
136	// MarshalJSON 在未启用键值应用时保持原有输出形状；启用时强制输出
137	// finalAppliedIndex、finalKV（空表为 {}）与 finalApplyError（无错误为 null）。
138	func (o ReplicateOutput) MarshalJSON() ([]byte, error) {
139		type alias ReplicateOutput
140		if !o.applyFields {
141			return json.Marshal(alias(o))
142		}
143		applied := 0
144		if o.FinalAppliedIndex != nil {
145			applied = *o.FinalAppliedIndex
146		}
147		kv := o.FinalKV
148		if kv == nil {
149			kv = map[string]string{}
150		}
151		return json.Marshal(struct {
152			alias
153			FinalAppliedIndex int               `json:"finalAppliedIndex"`
154			FinalKV           map[string]string `json:"finalKV"`
155			FinalApplyError   *ApplyError       `json:"finalApplyError"`
156		}{
157			alias:             alias(o),
158			FinalAppliedIndex: applied,
159			FinalKV:           kv,
160			FinalApplyError:   o.FinalApplyError,
161		})
162	}
163	
164	// UnmarshalJSON 读取结果时按 JSON 中是否出现最终应用字段恢复 applyFields，
165	// 语义同 AppendResult.UnmarshalJSON：出现时再次编码保留 finalAppliedIndex、
166	// finalKV（空表为 {}）与 finalApplyError（无错误为 null）；未出现时整个对象
167	// 被完整替换，不残留上一次读入的键值表、错误或应用位置。Results 中每条请求
168	// 结果由 AppendResult.UnmarshalJSON 各自恢复。字段类型错误照常返回解码错误。
169	func (o *ReplicateOutput) UnmarshalJSON(data []byte) error {
170		type alias ReplicateOutput
171		var decoded alias
172		if err := json.Unmarshal(data, &decoded); err != nil {
173			return err
174		}
175		present, err := jsonHasAnyKey(data, "finalAppliedIndex", "finalKV", "finalApplyError")
176		if err != nil {
177			return err
178		}
179		*o = ReplicateOutput(decoded)
180		o.applyFields = present
181		return nil
182	}
183	
184	// 拒绝原因（稳定标识符，帮助文档中有说明）。
185	const (
186		ReasonOK                      = "ok"
187		ReasonStaleTerm               = "stale term: leader term is lower than current term"
188		ReasonRequestTermNegative     = "invalid request: term is negative"
189		ReasonPrevLogIndexNegative    = "invalid request: prevLogIndex is negative"
190		ReasonPrevLogTermNegative     = "invalid request: prevLogTerm is negative"
191		ReasonLeaderCommitNegative    = "invalid request: leaderCommit is negative"
192		ReasonEmptyEntryTerm          = "invalid request: log entry has zero term"
193		ReasonEntryIndexGap           = "invalid request: entries are not consecutive from prevLogIndex+1"
194		ReasonEntryTermDecreases      = "invalid request: entry terms are not non-decreasing"
195		ReasonEntryTermExceedsReqTerm = "invalid request: entry term exceeds request term"
196		ReasonPrevLogMismatch         = "prev log mismatch: entry at prevLogIndex is missing or has a different term"
197		ReasonCommandConflictSameTerm = "entry conflict: same index and term but different command"
198		ReasonWouldOverwriteCommitted = "would overwrite committed entry"
199	)
200	
201	type replicateState struct {
202		currentTerm    int
203		committedIndex int
204		log            []LogEntry // log[i].Index == i+1
205	}
206	
207	// ReplicateOptions 控制 Replicate 的可选行为。零值保持原有处理与输出。
208	type ReplicateOptions struct {
209		// ApplyKV 为 true 时把已提交命令解释为键值操作（set/delete），在本次
210		// 调用内从空键值表开始，随提交位置推进按日志次序逐条应用；为 false
211		// 时命令仍是不加解释的任意字符串。
212		ApplyKV bool
213	}
214	
215	// Replicate 校验初始状态并顺序应用全部复制请求，返回逐次结果与最终状态。
216	// 初始状态非法时返回错误（调用方应以非零退出码结束）。单条请求违反字段规则
217	// 时只记录一次拒绝、不改变任何状态，随后继续处理下一条请求。
218	func Replicate(initial InitialState, requests []AppendRequest) (ReplicateOutput, error) {
219		return ReplicateWithOptions(initial, requests, ReplicateOptions{})
220	}
221	
222	// ReplicateWithOptions 与 Replicate 相同，但可通过 ReplicateOptions 启用
223	// 可选行为（如键值应用）。
224	func ReplicateWithOptions(initial InitialState, requests []AppendRequest, opts ReplicateOptions) (ReplicateOutput, error) {
225		state, err := newReplicateState(initial)
226		if err != nil {
227			return ReplicateOutput{}, err
228		}
229	
230		var applier *kvApplier
231		if opts.ApplyKV {
232			applier = newKVApplier()
233			// 先按索引顺序应用初始日志中已提交的前缀，再顺序处理复制请求。
234			applier.applyUpTo(state.log, state.committedIndex)
235		}
236	
237		results := make([]AppendResult, 0, len(requests))
238		for _, request := range requests {
239			result := state.apply(request)
240			if applier != nil {
241				// 每条请求处理结束后，只应用新提交且尚未应用的日志；应用失败
242				// 不改变复制的接受与否、提交位置或拒绝原因。
243				applier.applyUpTo(state.log, state.committedIndex)
244				applied := applier.appliedIndex
245				result.AppliedIndex = &applied
246				result.ApplyError = applier.err
247				result.applyFields = true
248			}
249			results = append(results, result)
250		}
251		finalLog := append([]LogEntry{}, state.log...)
252		if finalLog == nil {
253			finalLog = []LogEntry{}
254		}
255		output := ReplicateOutput{
256			Results:             results,
257			FinalTerm:           state.currentTerm,
258			FinalCommittedIndex: state.committedIndex,
259			FinalLog:            finalLog,
260		}
261		if applier != nil {
262			applied := applier.appliedIndex
263			output.FinalAppliedIndex = &applied
264			output.FinalKV = applier.kv
265			output.FinalApplyError = applier.err
266			output.applyFields = true
267		}
268		return output, nil
269	}
270	
271	func newReplicateState(initial InitialState) (replicateState, error) {
272		if initial.CurrentTerm < 0 {
273			return replicateState{}, fmt.Errorf("invalid initial state: currentTerm must be a non-negative integer")
274		}
275		if initial.CommittedIndex < 0 {
276			return replicateState{}, fmt.Errorf("invalid initial state: committedIndex must be a non-negative integer")
277		}
278		if initial.CommittedIndex > len(initial.Log) {
279			return replicateState{}, fmt.Errorf("invalid initial state: committedIndex %d exceeds log length %d", initial.CommittedIndex, len(initial.Log))
280		}
281		log := append([]LogEntry(nil), initial.Log...)
282		for i, entry := range log {
283			expected := i + 1
284			if entry.Index != expected {
285				return replicateState{}, fmt.Errorf("invalid initial state: log entry %d has non-consecutive index %d", expected, entry.Index)
286			}
287			if entry.Term <= 0 {
288				return replicateState{}, fmt.Errorf("invalid initial state: log entry %d has non-positive term %d", expected, entry.Term)
289			}
290			if i > 0 && entry.Term < log[i-1].Term {
291				return replicateState{}, fmt.Errorf("invalid initial state: log entry %d term %d is lower than previous term %d", expected, entry.Term, log[i-1].Term)
292			}
293			if entry.Term > initial.CurrentTerm {
294				return replicateState{}, fmt.Errorf("invalid initial state: log entry %d term %d exceeds currentTerm %d", expected, entry.Term, initial.CurrentTerm)
295			}
296		}
297		return replicateState{
298			currentTerm:    initial.CurrentTerm,
299			committedIndex: initial.CommittedIndex,
300			log:            log,
301		}, nil
302	}
303	
304	// termAt 返回索引 idx 处条目的任期；idx 为 0 时是日志起点哨兵，超出日志长度时 ok 为 false。
305	func (s *replicateState) termAt(idx int) (term int, ok bool) {
306		switch {
307		case idx == 0:
308			return 0, true
309		case idx < 0 || idx > len(s.log):
310			return 0, false
311		default:
312			return s.log[idx-1].Term, true
313		}
314	}
315	
316	// apply 处理单条请求。整个操作是原子的：任何拒绝都不会在日志、已提交索引上
317	// 留下部分变更；唯一例外是较高任期带来的 currentTerm 更新，按规则必须保留。
318	func (s *replicateState) apply(request AppendRequest) AppendResult {
319		snapshot := *s
320		accepted, reason := s.tryApply(request)
321		if !accepted {
322			// 回滚日志与提交位置；较高任期更新（若已发生）保留在 s.currentTerm 中。
323			s.log = snapshot.log
324			s.committedIndex = snapshot.committedIndex
325		}
326		return AppendResult{
327			Accepted:       accepted,
328			Reason:         reason,
329			Term:           s.currentTerm,
330			CommittedIndex: s.committedIndex,
331		}
332	}
333	
334	func (s *replicateState) tryApply(request AppendRequest) (bool, string) {
335		// 规则 1：先做字段合法性校验。违反字段规则的请求只记录拒绝、不改变任何
336		// 状态——即使它携带更高任期，也不能更新节点。
337		if reason := validateRequest(request); reason != ReasonOK {
338			return false, reason
339		}
340	
341		// 规则 2：较低任期直接拒绝，状态（含任期）完全不变。
342		if request.Term < s.currentTerm {
343			return false, ReasonStaleTerm
344		}
345	
346		// 规则 3：首条目任期不得低于前一条日志任期（整段日志必须不下降）。
347		// 这仍属于字段规则，放在任期更新之前：非法请求不能借高任期改变节点。
348		if len(request.Entries) > 0 && request.Entries[0].Term < request.PrevLogTerm {
349			return false, ReasonEntryTermDecreases
350		}
351	
352		// 规则 4：较高任期先更新当前任期，再核对日志；之后即便因前缀不匹配被拒，
353		// 任期更新也保留。
354		if request.Term > s.currentTerm {
355			s.currentTerm = request.Term
356		}
357	
358		// 规则 5：前一条日志必须存在且任期相同。索引 0 始终只与任期 0 匹配。
359		prevTerm, ok := s.termAt(request.PrevLogIndex)
360		if !ok || prevTerm != request.PrevLogTerm {
361			return false, ReasonPrevLogMismatch
362		}
363	
364		// 规则 6：把待追加条目与现有位置逐一比对——全部检查通过后才落笔，
365		// 保证“即使前面已发现可追加内容，也不能留下部分变更”。第一个任期冲突
366		// 位置之后的旧日志都会被整段替换，因此只需在冲突位置之前检查命令冲突。
367		// matched 是请求条目中与现有位置完全相同（同任期同命令）的连续前缀长度；
368		// 超出本地日志长度的位置尚不存在，不属于已匹配，稍后追加。
369		start := request.PrevLogIndex // entries[k] 对应索引 start+1+k
370		cutAt := -1                   // 首个任期不同的现有位置（切片下标）
371		matched := 0
372		for offset, incoming := range request.Entries {
373			idx := start + 1 + offset
374			if idx > len(s.log) {
375				break // 该位置及之后都不存在：稍后整体追加
376			}
377			existing := s.log[idx-1]
378			switch {
379			case existing.Term == incoming.Term && existing.Command == incoming.Command:
380				// 完全相同：保留，重复请求不会产生重复条目。
381				matched++
382			case existing.Term == incoming.Term:
383				// 同索引同任期却命令不同：拒绝，日志与提交位置保持原样。
384				return false, ReasonCommandConflictSameTerm
385			case idx <= s.committedIndex:
386				// 不同任期意味着要覆盖该处及其后缀；已提交条目不可覆盖。
387				return false, ReasonWouldOverwriteCommitted
388			default:
389				// 未提交位置上的任期冲突：截断到此处再追加，其后旧日志整段丢弃。
390				cutAt = idx - 1
391			}
392			if cutAt >= 0 {
393				break
394			}
395		}
396	
397		// 规则 7：合并日志。全部匹配的短请求（matched == len(entries)）不删除
398		// 本地多出的尾部；任期冲突时截断冲突位置及其后缀；其余缺失位置追加。
399		if cutAt >= 0 {
400			matched = cutAt - start
401			s.log = append([]LogEntry(nil), s.log[:cutAt]...)
402		}
403		if matched < len(request.Entries) {
404			s.log = append(s.log, request.Entries[matched:]...)
405		}
406	
407		// 规则 8：提交位置推进至 leaderCommit 与本次确认的最后索引的较小值，
408		// 且不会后退。空条目请求的确认位置就是前一条索引。
409		lastIndex := request.PrevLogIndex + len(request.Entries)
410		newCommit := request.LeaderCommit
411		if lastIndex < newCommit {
412			newCommit = lastIndex
413		}
414		if newCommit > s.committedIndex {
415			s.committedIndex = newCommit
416		}
417		return true, ReasonOK
418	}
419	
420	func validateRequest(request AppendRequest) string {
421		if request.Term < 0 {
422			return ReasonRequestTermNegative
423		}
424		if request.PrevLogIndex < 0 {
425			return ReasonPrevLogIndexNegative
426		}
427		if request.PrevLogTerm < 0 {
428			return ReasonPrevLogTermNegative
429		}
430		if request.LeaderCommit < 0 {
431			return ReasonLeaderCommitNegative
432		}
433		// 条目必须从前一条索引加 1 开始连续排列；任期为正、沿请求条目自身
434		// 不下降，且不得超过请求（领导者）任期。与 prevLogTerm 的衔接在
435		// tryApply 中单独检查。索引 0 是哨兵，真实条目索引必为正。
436		for i, entry := range request.Entries {
437			if entry.Index != request.PrevLogIndex+1+i {
438				return ReasonEntryIndexGap
439			}
440			if entry.Term <= 0 {
441				return ReasonEmptyEntryTerm
442			}
443			if i > 0 && entry.Term < request.Entries[i-1].Term {
444				return ReasonEntryTermDecreases
445			}
446			if entry.Term > request.Term {
447				return ReasonEntryTermExceedsReqTerm
448			}
449		}
450		return ReasonOK
451	}
452

