321		// 无错误时错误字段输出 null 而不是消失。
322		if !strings.Contains(body, `"applyError":null`) || !strings.Contains(body, `"finalApplyError":null`) {
323			t.Fatalf("empty apply errors must serialize as null: %s", body)
324		}
325	}
